class TaskBinding {static class OddCheck implements Property<Integer>{public boolean test(Integer x){return x%2!=0;}}static class LengthCheck implements Property<String>{public boolean test(String x){return x.length()>3;}}static int integers(Integer[]a,int example){return Counter.count(a,new OddCheck());}static int strings(String[]a,int example){return Counter.count(a,new LengthCheck());}}
